// The plain voice strips the draw text's MANDATORY lines (the page's fmtDraw, verbatim).
export const fmtDrawForVoice = (voice, ...a) => { const t = formatDrawForAI(...a); return voice === 'plain' ? t.split('\n').filter(l => !l.includes('MANDATORY:')).join('\n') : t; };


// .528: THE EZ SYSTEM PROMPT, ASSEMBLED ONCE. The kernel (BASE_SYSTEM) and EZ_RULES had grown the same seven rail
// paragraphs (wellbeing, own care, medicine once, backstory, trauma, body causes, the stance) — ~2.4k tokens said
// twice. EZ_RULES is the authority for EZ; any kernel paragraph whose opening matches one in EZ_RULES is dropped
// here. /advanced still gets the whole kernel. No persona block: the register rules are the persona.
const paraKey = (p) => p.replace(/\s+/g, ' ').trim().slice(0, 60).toLowerCase();
export function ezSystem(base, voice) {
  const have = new Set(EZ_RULES.split(/\n\n+/).map(paraKey).filter((k) => k.length >= 40));
  const kept = base.split(/\n\n+/).filter((p) => !have.has(paraKey(p)));
  const rules = VOICES[voice]?.rules ? `\n\n${VOICES[voice].rules}` : '';
  return `${kept.join('\n\n')}\n\n${EZ_RULES}${rules}`;
}
